using System.Globalization;
using System.Text;

namespace Lustral.Core.GameData;

/// <summary>
/// The layouts used to read companyName, productName and bundleVersion (<c>Application.version</c>) from PlayerSettings
/// in each Unity version without type trees, from <c>PlayerSettingsLayouts.txt</c> (generated by
/// <c>tools/playersettings-layouts.cs</c>). A game's globalgamemanagers identifies its PlayerSettings layout by type hash,
/// so matches are exact. Unity versions newer than the table have no match, and no layout is guessed, because an
/// incorrect layout reads the wrong string without failing. Guessing with the previous Unity version's layout and
/// confirming the company and product names against app.info was evaluated against every layout change in the table:
/// where a change precedes bundleVersion, it returned a plausible wrong version (usually "1.0", from the strings before
/// bundleVersion, which is also Unity's default version) in 21 of 112 changes, and the correct one in 18.
/// </summary>
internal sealed class PlayerSettingsLayouts
{
    private const string ResourceName = "Lustral.PlayerSettingsLayouts.txt";
    private static readonly UTF8Encoding StrictUtf8 = new(encoderShouldEmitUTF8Identifier: false, throwOnInvalidBytes: true);
    private static PlayerSettingsLayouts? s_embedded;

    private readonly Dictionary<string, Layout> _byHash = new(StringComparer.Ordinal);

    private PlayerSettingsLayouts()
    {
    }

    /// <summary>The table embedded in Lustral.Core.</summary>
    public static PlayerSettingsLayouts Embedded => s_embedded ??= Parse(ReadResource());

    /// <exception cref="FormatException">The text is not a valid layout table.</exception>
    public static PlayerSettingsLayouts Parse(string text)
    {
        var result = new PlayerSettingsLayouts();
        var layouts = new Dictionary<int, Layout>();
        foreach (var rawLine in text.Split('\n'))
        {
            var line = rawLine.Trim();
            if (line.Length == 0 || line[0] == '#')
                continue;
            var parts = line.Split([' '], StringSplitOptions.RemoveEmptyEntries);
            if (parts[0] == "L" && parts.Length > 2)
            {
                var id = int.Parse(parts[1], NumberStyles.None, CultureInfo.InvariantCulture);
                layouts[id] = new Layout(id, Compile(parts, 2));
            }
            else if (parts[0] == "V" && parts.Length == 4
                && layouts.TryGetValue(int.Parse(parts[3], NumberStyles.None, CultureInfo.InvariantCulture), out var layout))
            {
                layout.FirstVersion ??= parts[1];
                result._byHash[parts[2].ToLowerInvariant()] = layout;
            }
            else
                throw new FormatException($"invalid line in the PlayerSettings layouts: {line}");
        }
        return result;
    }

    /// <summary>Returns the layout of the PlayerSettings type with the specified hash, if a known Unity version uses it.</summary>
    public Layout? ForTypeHash(byte[] hash) =>
        _byHash.TryGetValue(ToHex(hash), out var layout) ? layout : null;

    /// <summary>
    /// Reads companyName, productName and bundleVersion from PlayerSettings data using a layout. Returns null if the layout
    /// does not match the data (a string or array extends past the end, or text is not valid UTF-8).
    /// </summary>
    public static (string Company, string Product, string Version)? TryRead(byte[] data, Layout layout, bool bigEndian = false)
    {
        try
        {
            var reader = new ByteReader(data, bigEndian);
            var captured = new string?[3];
            Run(layout.Operations, 0, layout.Operations.Length, reader, captured);
            return captured[0] is { } company && captured[1] is { } product && captured[2] is { } version
                ? (company, product, version)
                : null;
        }
        catch (Exception e) when (e is InvalidDataException or DecoderFallbackException or ArgumentException or OverflowException)
        {
            return null;
        }
    }

    private static void Run(Operation[] operations, int from, int to, ByteReader reader, string?[] captured)
    {
        for (var i = from; i < to; i++)
        {
            var operation = operations[i];
            switch (operation.Kind)
            {
                case OperationKind.Skip:
                    reader.Skip(operation.Value);
                    break;
                case OperationKind.Align:
                    reader.Align(4);
                    break;
                case OperationKind.String:
                    var length = reader.ReadInt32();
                    if (length < 0 || length > reader.Remaining)
                        throw new InvalidDataException("string extends past the end");
                    captured[operation.Value] = StrictUtf8.GetString(reader.ReadBytes(length));
                    break;
                case OperationKind.Array:
                    var count = reader.ReadInt32();
                    if (count < 0 || count > reader.Remaining)
                        throw new InvalidDataException("array extends past the end");
                    var end = operation.Value;
                    // Arrays of fixed-size elements (the most common case) are skipped in a single step.
                    if (end == i + 2 && operations[i + 1].Kind == OperationKind.Skip)
                        reader.Skip(checked(count * operations[i + 1].Value));
                    else
                    {
                        for (var element = 0; element < count; element++)
                            Run(operations, i + 1, end, reader, captured);
                    }
                    i = end; // Past the closing bracket.
                    break;
            }
        }
    }

    private static Operation[] Compile(string[] tokens, int start)
    {
        var operations = new List<Operation>();
        var open = new Stack<int>();
        for (var i = start; i < tokens.Length; i++)
        {
            var token = tokens[i];
            switch (token)
            {
                case "!":
                    operations.Add(new Operation(OperationKind.Align, 0));
                    break;
                case "[":
                    open.Push(operations.Count);
                    operations.Add(new Operation(OperationKind.Array, 0));
                    break;
                case "]":
                    if (open.Count == 0)
                        throw new FormatException("unbalanced ] in a PlayerSettings layout");
                    var opening = open.Pop();
                    operations[opening] = new Operation(OperationKind.Array, operations.Count);
                    operations.Add(new Operation(OperationKind.End, 0));
                    break;
                case "s:company":
                    operations.Add(new Operation(OperationKind.String, 0));
                    break;
                case "s:product":
                    operations.Add(new Operation(OperationKind.String, 1));
                    break;
                case "s:version":
                    operations.Add(new Operation(OperationKind.String, 2));
                    break;
                default:
                    operations.Add(new Operation(OperationKind.Skip, int.Parse(token, NumberStyles.None, CultureInfo.InvariantCulture)));
                    break;
            }
        }
        if (open.Count > 0)
            throw new FormatException("unbalanced [ in a PlayerSettings layout");
        return operations.ToArray();
    }

    private static string ReadResource()
    {
        using var stream = typeof(PlayerSettingsLayouts).Assembly.GetManifestResourceStream(ResourceName)
            ?? throw new InvalidOperationException($"{ResourceName} is not embedded in Lustral.Core");
        using var reader = new StreamReader(stream, Encoding.UTF8);
        return reader.ReadToEnd();
    }

    private static string ToHex(byte[] bytes)
    {
        var builder = new StringBuilder(bytes.Length * 2);
        foreach (var b in bytes)
            builder.Append(b.ToString("x2", CultureInfo.InvariantCulture));
        return builder.ToString();
    }

    internal enum OperationKind
    {
        Skip,
        Align,
        String,
        Array,
        End,
    }

    // Skip: the byte count. String: the capture (company, product or version). Array: the index of its End.
    internal readonly record struct Operation(OperationKind Kind, int Value);

    internal sealed class Layout(int id, Operation[] operations)
    {
        public int Id { get; } = id;

        /// <summary>The first Unity version listed with this layout, for messages.</summary>
        public string? FirstVersion { get; set; }

        internal Operation[] Operations { get; } = operations;
    }
}
